payload.text:
To implement the requested features (Replay without API calls & Playback Speed Control), I will update **`components/TypingView.tsx`**.

Here is the summary of changes:
1.  **Audio Caching**: Introduced `cachedAudioBuffer` state. The app now checks this cache before calling the Gemini API. If audio exists, it plays immediately without a network request. The cache is automatically cleared when the content changes.
2.  **Playback Speed**: Added `playbackSpeed` state and a UI button to cycle through speeds (0.75x, 1.0x, 1.25x).
3.  **Live Speed Adjustment**: If you change the speed while audio is playing, it updates immediately using the Web Audio API's `playbackRate` parameter.

# Updated files:

## components/TypingView.tsx

-   Added `cachedAudioBuffer` to store decoded audio for replaying.
-   Added `playbackSpeed` state and controls.
-   Updated `playAudio` to use the cache if available.
-   Added a speed toggle button (e.g., "1.0x") next to the play button.

```tsx
<change>
    <file>components/TypingView.tsx</file>
    <description>Add audio caching for replay without API calls and playback speed control</description>
    <content><![CDATA[
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { TypingContent, UserProfile, UserContent } from '../types';
import { generateTypingContent, generateSpeech } from '../services/geminiService';
import { addActivity, getLibrary } from '../services/storageService';
import { DRILL_TOPICS } from '../constants';
import { RefreshCw, Play, Keyboard, Eye, EyeOff, BookOpen, Zap, Star, Sparkles, LayoutGrid, Book, Volume2, StopCircle, Loader2, Gauge } from 'lucide-react';

interface TypingViewProps {
  user: UserProfile;
  onComplete: (user: UserProfile) => void;
  initialData?: { text: string; title: string } | null;
}

// --- Audio Helpers for Gemini TTS ---
function decodeBase64(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

async function decodeAudioData(
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number = 24000,
    numChannels: number = 1,
): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
        const channelData = buffer.getChannelData(channel);
        for (let i = 0; i < frameCount; i++) {
            channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
        }
    }
    return buffer;
}

const TypingView: React.FC<TypingViewProps> = ({ user, onComplete, initialData }) => {
  const [content, setContent] = useState<TypingContent | null>(null);
  const [inputValue, setInputValue] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [wpm, setWpm] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [showPhonetic, setShowPhonetic] = useState(true);
  const [showTranslation, setShowTranslation] = useState(false);
  const [finished, setFinished] = useState(false);

  // Audio State
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [cachedAudioBuffer, setCachedAudioBuffer] = useState<AudioBuffer | null>(null);
  const [playbackSpeed, setPlaybackSpeed] = useState(1.0);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  // Selection Mode State
  const [activeTab, setActiveTab] = useState<'ai' | 'memory'>('ai');
  const [libraryItems, setLibraryItems] = useState<UserContent[]>([]);

  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
      setLibraryItems(getLibrary().filter(i => i.language === user.learningLanguage));
  }, [user.learningLanguage]);

  // Cleanup audio on unmount
  useEffect(() => {
      return () => {
          stopAudio();
          if (audioContextRef.current) {
              audioContextRef.current.close();
              audioContextRef.current = null;
          }
      };
  }, []);

  // Reset cache and stop audio when content changes
  useEffect(() => {
      stopAudio();
      setCachedAudioBuffer(null);
  }, [content]);

  const stopAudio = () => {
      if (audioSourceRef.current) {
          try {
              audioSourceRef.current.stop();
          } catch (e) {
              // Ignore if already stopped
          }
          audioSourceRef.current = null;
      }
      setIsSpeaking(false);
      setIsGeneratingAudio(false);
      window.speechSynthesis.cancel();
  };

  const toggleSpeed = () => {
      const speeds = [0.75, 1.0, 1.25];
      const nextIdx = (speeds.indexOf(playbackSpeed) + 1) % speeds.length;
      const newSpeed = speeds[nextIdx];
      setPlaybackSpeed(newSpeed);

      // Apply to currently playing audio immediately
      if (isSpeaking && audioSourceRef.current && audioContextRef.current) {
          audioSourceRef.current.playbackRate.setValueAtTime(newSpeed, audioContextRef.current.currentTime);
      }
  };

  const playAudio = async () => {
      if (!content) return;

      // Toggle logic: If playing, stop.
      if (isSpeaking) {
          stopAudio();
          return;
      }

      setIsGeneratingAudio(true);

      try {
          // 1. Check Cache
          let buffer = cachedAudioBuffer;

          // 2. If not cached, fetch from Gemini
          if (!buffer) {
            const base64Audio = await generateSpeech(content.text);
            if (!base64Audio) {
                throw new Error("No audio returned");
            }

            // Init Audio Context if needed
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }
            const ctx = audioContextRef.current;

            // Decode
            const bytes = decodeBase64(base64Audio);
            buffer = await decodeAudioData(bytes, ctx);
            setCachedAudioBuffer(buffer);
          } else {
             setIsGeneratingAudio(false); // Cache hit, no loading state needed
          }

          // 3. Play
          if (!audioContextRef.current) {
             audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
          }
          const ctx = audioContextRef.current;

          // Ensure context is running (browsers suspend it sometimes)
          if (ctx.state === 'suspended') {
              await ctx.resume();
          }

          const source = ctx.createBufferSource();
          source.buffer = buffer;
          source.playbackRate.value = playbackSpeed; // Apply speed
          source.connect(ctx.destination);

          source.onended = () => setIsSpeaking(false);

          audioSourceRef.current = source;
          setIsGeneratingAudio(false);
          setIsSpeaking(true);
          source.start(0);

      } catch (error) {
          console.error("Audio playback failed:", error);
          setIsGeneratingAudio(false);
          setIsSpeaking(false);

          // Fallback to browser TTS if Gemini fails
          const utterance = new SpeechSynthesisUtterance(content.text);
          // Attempt to map language code, simple fallback
          utterance.lang = 'en-US'; 
          utterance.rate = playbackSpeed;
          window.speechSynthesis.speak(utterance);
      }
  };

  const fetchContent = useCallback(async (selectedTopic?: string) => {
    stopAudio();
    setIsLoading(true);
    setInputValue('');
    setStartTime(null);
    setWpm(0);
    setFinished(false);
    try {
      const data = await generateTypingContent(user.learningLanguage, user.cefrLevel, selectedTopic);
      setContent(data);
      // Auto focus after loading
      setTimeout(() => inputRef.current?.focus(), 100);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  }, [user.learningLanguage, user.cefrLevel]);

  // Handle Initial Data or Clean Start
  useEffect(() => {
    if (initialData) {
        stopAudio();
        // Use provided content (e.g. from Library)
        setContent({
            text: initialData.text,
            topic: initialData.title,
            translation: "Custom Memory Bank content",
            phoneticGuide: "", // Custom content currently doesn't generate guide
            keyVocabulary: []
        });
        setInputValue('');
        setStartTime(null);
        setWpm(0);
        setFinished(false);
        setTimeout(() => inputRef.current?.focus(), 100);
    } else {
        // Reset if we switch back to generic mode without data
        stopAudio();
        setContent(null);
        setInputValue('');
        setFinished(false);
    }
  }, [initialData]);

  const handleInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (finished) return;
    const val = e.target.value;
    if (!startTime) {
      setStartTime(Date.now());
    }
    setInputValue(val);

    // WPM Calc
    if (startTime) {
      const timeElapsed = (Date.now() - startTime) / 60000; // in minutes
      const wordsTyped = val.length / 5; // standard avg word length
      setWpm(Math.round(wordsTyped / timeElapsed) || 0);
    }

    // Check Completion
    if (content && val === content.text) {
        setFinished(true);
        handleCompletion(val.length);
    }
  };

  const handleCompletion = (length: number) => {
      // Calculate XP: Base 20 + 1 per 5 chars + bonus for speed
      const baseXP = 20;
      const lengthXP = Math.floor(length / 5);
      const speedBonus = wpm > 40 ? 10 : 0;
      const totalXP = baseXP + lengthXP + speedBonus;

      const { user: updatedUser } = addActivity(
          user,
          'typing',
          user.learningLanguage,
          totalXP,
          `Completed Drill: ${content?.topic}`,
          {
              wpm: wpm,
              accuracy: 100, // Hardcoded for now since we require perfect match eventually or visual errors
              wordCount: Math.floor(length / 5)
          }
      );
      onComplete(updatedUser);
  };

  const handleUseLibraryItem = (item: UserContent) => {
      stopAudio();
      setContent({
            text: item.content,
            topic: item.title,
            translation: "From Memory Bank",
            phoneticGuide: "", 
            keyVocabulary: []
        });
        setInputValue('');
        setStartTime(null);
        setWpm(0);
        setFinished(false);
        setTimeout(() => inputRef.current?.focus(), 100);
  };

  // Render text with highlighting
  const renderText = () => {
    if (!content) return null;
    const targetText = content.text;

    return (
      <div className="text-2xl md:text-3xl font-mono leading-relaxed break-words tracking-wide">
        {targetText.split('').map((char, index) => {
          let colorClass = 'text-gray-500'; // Untyped
          let bgClass = 'bg-transparent';
          const isCurrent = index === inputValue.length;

          if (index < inputValue.length) {
            if (inputValue[index] === char) {
              colorClass = 'text-green-400';
            } else {
              colorClass = 'text-red-400';
              bgClass = 'bg-red-900/30';
            }
          }

          return (
            <span key={index} className={`relative ${colorClass} ${bgClass} transition-colors duration-75`}>
              {isCurrent && (
                <span className="absolute -left-[1px] -top-1 h-8 w-[2px] bg-secondary animate-pulse" />
              )}
              {char}
            </span>
          );
        })}
      </div>
    );
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Controls Header */}
      <div className="flex flex-wrap items-center justify-between gap-4 bg-card p-4 rounded-xl border border-gray-700">
        <div className="flex items-center gap-3">
            <span className="px-3 py-1 rounded-full bg-primary/20 text-primary text-sm font-bold border border-primary/30">
                {user.cefrLevel}
            </span>

            {/* Audio Controls */}
            {content && (
                <div className="flex items-center gap-1 bg-gray-800/50 rounded-lg p-1 border border-gray-700">
                    <button
                        onClick={playAudio}
                        disabled={isGeneratingAudio && !cachedAudioBuffer}
                        className={`p-2 rounded-md transition-colors flex items-center gap-2 ${isSpeaking ? 'bg-green-500/20 text-green-400 animate-pulse' : 'hover:bg-gray-700 text-gray-300'}`}
                        title={isSpeaking ? "Stop" : (cachedAudioBuffer ? "Replay Audio" : "Generate & Play Audio")}
                    >
                        {(isGeneratingAudio && !cachedAudioBuffer) ? (
                            <Loader2 size={18} className="animate-spin text-secondary" />
                        ) : isSpeaking ? (
                            <StopCircle size={18} />
                        ) : (
                            <Volume2 size={18} />
                        )}
                    </button>

                    {/* Speed Toggle */}
                    <button
                        onClick={toggleSpeed}
                        className="p-1 px-2 text-xs font-mono font-bold text-gray-400 hover:text-white hover:bg-gray-700 rounded transition-colors"
                        title="Playback Speed"
                    >
                        {playbackSpeed}x
                    </button>
                </div>
            )}

            {content?.phoneticGuide && (
                <button 
                    onClick={() => setShowPhonetic(!showPhonetic)}
                    className={`p-2 rounded-lg transition-colors ${showPhonetic ? 'bg-secondary/20 text-secondary' : 'text-gray-400 hover:text-gray-200'}`}
                    title="Toggle Phonetic Guide"
                >
                    <Keyboard size={18} />
                </button>
            )}
            <button 
                onClick={() => setShowTranslation(!showTranslation)}
                className={`p-2 rounded-lg transition-colors ${showTranslation ? 'bg-blue-500/20 text-blue-400' : 'text-gray-400 hover:text-gray-200'}`}
                title="Toggle Translation"
            >
                 {showTranslation ? <Eye size={18} /> : <EyeOff size={18} />}
            </button>
        </div>

        <div className="flex items-center gap-6">
            <div className="flex flex-col items-end">
                <span className="text-xs text-gray-500 uppercase tracking-widest">Speed</span>
                <span className="text-xl font-mono font-bold text-white">{wpm} <span className="text-sm font-normal text-gray-500">WPM</span></span>
            </div>
            {content && (
                <button 
                    onClick={() => setContent(null)} 
                    disabled={isLoading}
                    className="flex items-center gap-2 px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg transition-colors text-sm font-medium"
                >
                    <RefreshCw size={16} className={isLoading ? "animate-spin" : ""} />
                    Change Drill
                </button>
            )}
        </div>
      </div>

      {/* Main Content / Setup Area */}
      <div className="relative">

      {isLoading ? (
          <div className="bg-dark rounded-2xl p-12 border border-gray-800 shadow-2xl min-h-[300px] flex items-center justify-center flex-col gap-4">
             <div className="w-12 h-12 border-4 border-secondary border-t-transparent rounded-full animate-spin"></div>
             <p className="text-gray-400 animate-pulse">Generating tailored practice...</p>
          </div>
        ) : !content ? (
            // Setup Screen
            <div className="bg-dark rounded-2xl p-6 md:p-8 border border-gray-800 shadow-2xl min-h-[400px]">
                 <div className="text-center mb-8">
                     <h3 className="text-2xl font-bold text-white mb-2">Choose your Drill</h3>
                     <p className="text-gray-400">Select an AI-generated topic or review your memory bank.</p>
                 </div>

                 {/* Tabs */}
                 <div className="flex justify-center gap-4 mb-8">
                     <button 
                        onClick={() => setActiveTab('ai')}
                        className={`flex items-center gap-2 px-6 py-3 rounded-xl font-bold transition-all ${activeTab === 'ai' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-gray-800 text-gray-400 hover:bg-gray-700'}`}
                     >
                        <LayoutGrid size={18} /> AI Topics
                     </button>
                     <button 
                        onClick={() => setActiveTab('memory')}
                        className={`flex items-center gap-2 px-6 py-3 rounded-xl font-bold transition-all ${activeTab === 'memory' ? 'bg-secondary text-white shadow-lg shadow-secondary/20' : 'bg-gray-800 text-gray-400 hover:bg-gray-700'}`}
                     >
                        <Book size={18} /> Memory Bank
                     </button>
                 </div>

                 {/* Content Selection */}
                 {activeTab === 'ai' ? (
                     <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3">
                         {DRILL_TOPICS.map(topic => (
                             <button
                                key={topic.id}
                                onClick={() => fetchContent(topic.label)}
                                className="flex flex-col items-center justify-center gap-2 p-4 bg-gray-800/50 hover:bg-gray-700 hover:scale-105 border border-gray-700 hover:border-primary/50 rounded-xl transition-all group"
                             >
                                 <span className="text-3xl grayscale group-hover:grayscale-0 transition-all">{topic.icon}</span>
                                 <span className="text-sm font-medium text-gray-300 group-hover:text-white">{topic.label}</span>
                             </button>
                         ))}
                         {/* Random Button */}
                         <button
                            onClick={() => fetchContent()}
                            className="flex flex-col items-center justify-center gap-2 p-4 bg-gradient-to-br from-gray-800 to-gray-700 hover:brightness-110 border border-gray-700 hover:border-white/30 rounded-xl transition-all"
                         >
                             <Sparkles size={32} className="text-yellow-400" />
                             <span className="text-sm font-bold text-white">Surprise Me</span>
                         </button>
                     </div>
                 ) : (
                     <div className="space-y-3">
                         {libraryItems.length === 0 ? (
                             <div className="text-center py-12 border-2 border-dashed border-gray-800 rounded-xl">
                                 <p className="text-gray-500 mb-4">Your Memory Bank is empty.</p>
                                 <div className="text-sm text-gray-600">Go to the Memory Bank tab to add your own paragraphs.</div>
                             </div>
                         ) : (
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                 {libraryItems.map(item => (
                                     <button
                                        key={item.id}
                                        onClick={() => handleUseLibraryItem(item)}
                                        className="text-left p-4 bg-gray-800/50 hover:bg-gray-700 border border-gray-700 hover:border-secondary/50 rounded-xl transition-all group"
                                     >
                                         <h4 className="font-bold text-gray-200 group-hover:text-white mb-1 truncate">{item.title}</h4>
                                         <p className="text-xs text-gray-500 truncate">{item.content}</p>
                                     </button>
                                 ))}
                             </div>
                         )}
                     </div>
                 )}
            </div>
        ) : (
          <div 
            className="bg-dark rounded-2xl p-8 md:p-12 border border-gray-800 shadow-2xl min-h-[300px] flex flex-col justify-center cursor-text"
            onClick={() => inputRef.current?.focus()}
          >
            <div className="space-y-6">
                {/* Phonetic / Input Hint */}
                {content.phoneticGuide && showPhonetic && (
                    <div className="text-gray-500 font-mono text-sm md:text-base leading-loose tracking-wide mb-2 opacity-70 select-none">
                        {content.phoneticGuide}
                    </div>
                )}

                {/* The Actual Text */}
                {renderText()}

                {/* Translation Overlay (if enabled) */}
                {showTranslation && (
                    <div className="mt-8 pt-6 border-t border-gray-800 text-blue-300/80 italic text-lg">
                        "{content.translation}"
                    </div>
                )}

                {/* Hidden Input */}
                <input
                ref={inputRef}
                type="text"
                className="opacity-0 absolute inset-0 cursor-default"
                value={inputValue}
                onChange={handleInput}
                autoFocus
                autoComplete="off"
                autoCorrect="off"
                autoCapitalize="off"
                spellCheck="false"
                />
            </div>
          </div>
        )}
      </div>

      {/* Success State */}
      {finished && (
        <div className="bg-green-900/20 border border-green-800 rounded-xl p-6 flex flex-col md:flex-row items-center justify-between gap-4 animate-in fade-in zoom-in duration-300">
            <div className="flex items-center gap-4">
                <div className="p-3 bg-green-500 rounded-full text-dark">
                    <Zap size={24} fill="currentColor" />
                </div>
                <div>
                    <h3 className="text-xl font-bold text-green-400">Drill Completed!</h3>
                    <p className="text-green-300/70">XP Awarded. Memory reinforced.</p>
                </div>
            </div>

            <div className="flex items-center gap-4">
                 <div className="flex flex-col items-center px-4 border-r border-green-800">
                     <span className="text-xs text-green-500/80 uppercase">XP Earned</span>
                     <span className="text-2xl font-bold text-white flex items-center gap-1">
                         <Star size={16} className="text-yellow-400" fill="currentColor" /> 
                         {/* Estimate XP shown here, real logic in handleCompletion */}
                         {20 + Math.floor(content!.text.length/5) + (wpm > 40 ? 10 : 0)}
                     </span>
                 </div>
                 <button 
                    onClick={() => {setContent(null); setFinished(false);}}
                    className="px-6 py-2 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg transition-colors flex items-center gap-2"
                >
                    Next Drill <Play size={16} />
                </button>
            </div>
        </div>
      )}

      {/* Vocabulary Cards */}
      {!isLoading && content && content.keyVocabulary.length > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-8">
              {content.keyVocabulary.map((item, idx) => (
                  <div key={idx} className="bg-card/50 p-4 rounded-xl border border-gray-800 hover:border-gray-600 transition-colors group">
                      <div className="flex items-center gap-2 mb-2">
                        <BookOpen size={14} className="text-secondary" />
                        <span className="text-xs text-gray-500 uppercase font-semibold">{item.partOfSpeech}</span>
                      </div>
                      <h4 className="text-lg font-bold text-white mb-1 group-hover:text-secondary transition-colors">{item.word}</h4>
                      <p className="text-sm text-gray-400">{item.meaning}</p>
                  </div>
              ))}
          </div>
      )}
    </div>
  );
};

export default TypingView;
]]></content>
</change>

