export const classifyInspiration = async (text: string, existingNodes: WritingNode[]): Promise<{ suggestedParentTitle: string; rationale: string }> => {
    // Simplify tree for context token limit
    const simpleTree = existingNodes.map(n => ({ id: n.id, title: n.title, type: n.type }));

    const prompt = `
        I have a loose idea/snippet: "${text.substring(0, 200)}...".
        Here is my current writing tree structure: ${JSON.stringify(simpleTree)}.

        Where does this snippet belong? Suggest the best existing parent Node Title.
        If it fits nowhere, suggest 'ROOT' or a new conceptual section name.

        Return ONLY valid JSON. No Markdown.
        Structure:
        {
          "suggestedParentTitle": "string",
          "rationale": "string"
        }
    `;

    try {
         const response = await ai.models.generateContent({
            model: MODEL_FAST,
            contents: prompt,
        });
        return parseAIJSON(response.text, { suggestedParentTitle: "Inspiration Box", rationale: "Could not classify." });
    } catch (error) {
        return { suggestedParentTitle: "Inspiration Box", rationale: "Could not classify." };
    }
};

