export default LibraryView;

import { UserProfile, ActivityLog, Language, CEFRLevel, DailyQuest, UserContent, LanguageProgress, WritingNode, VocabularyItem } from '../types';

const STORAGE_KEY_USER = 'linguaflow_user';
const STORAGE_KEY_LOGS = 'linguaflow_logs';
const STORAGE_KEY_LIBRARY = 'linguaflow_library';
const STORAGE_KEY_TREE = 'linguaflow_writing_tree';
const STORAGE_KEY_VOCAB = 'linguaflow_vocabulary';

// --- Helper: Date String ---
const getTodayString = () => new Date().toISOString().split('T')[0];

export const getUser = (): UserProfile | null => {
  const data = localStorage.getItem(STORAGE_KEY_USER);
  if (!data) return null;

  try {
    const parsed = JSON.parse(data);
    // Migration fallback
    if (parsed.xp !== undefined && !parsed.progress) {
        return {
            ...parsed,
            progress: {
                [parsed.learningLanguage]: {
                    xp: parsed.xp,
                    level: parsed.level,
                    cefrLevel: parsed.cefrLevel || CEFRLevel.A1,
                    totalWordsTyped: 0,
                    lastActive: Date.now(),
                    maxUnlockedStage: 0
                }
            }
        };
    }
    return parsed;
  } catch (e) {
    return null;
  }
};

export const saveUser = (user: UserProfile) => {
  localStorage.setItem(STORAGE_KEY_USER, JSON.stringify(user));
};

export const logoutUser = () => {
    localStorage.removeItem(STORAGE_KEY_USER);
};

export const registerUser = (username: string, nativeLanguage: Language, learningLanguage: Language, level: CEFRLevel): UserProfile => {
  const newUser: UserProfile = {
    username,
    nativeLanguage,
    learningLanguage,
    progress: {
        [learningLanguage]: {
            xp: 0,
            level: 1,
            cefrLevel: level,
            totalWordsTyped: 0,
            lastActive: Date.now(),
            maxUnlockedStage: 0
        }
    },
    currentStreak: 1,
    maxStreak: 1,
    lastActiveDate: getTodayString(),
    joinedDate: Date.now()
  };
  saveUser(newUser);
  return newUser;
};

// Ensure language progress exists when switching languages
export const ensureLanguageProgress = (user: UserProfile, lang: Language): UserProfile => {
    if (!user.progress[lang]) {
        user.progress[lang] = {
            xp: 0,
            level: 1,
            cefrLevel: CEFRLevel.A1,
            totalWordsTyped: 0,
            lastActive: Date.now(),
            maxUnlockedStage: 0
        };
        saveUser(user);
    }
    return user;
};

// --- Activity Logs ---

export const getLogs = (): ActivityLog[] => {
  const data = localStorage.getItem(STORAGE_KEY_LOGS);
  return data ? JSON.parse(data) : [];
};

export const addActivity = (
    user: UserProfile, 
    type: ActivityLog['type'], 
    language: Language,
    xp: number, 
    summary: string, 
    details: any
): { user: UserProfile, log: ActivityLog } => {

  // 1. Update User Stats (Multi-language support)
  const today = getTodayString();
  const isNewDay = user.lastActiveDate !== today;

  let updatedUser = { ...user };

  // Ensure progress object exists
  if (!updatedUser.progress[language]) {
      updatedUser = ensureLanguageProgress(updatedUser, language);
  }

  const langProgress = updatedUser.progress[language];

  // Update specific language progress
  langProgress.xp += xp;
  langProgress.lastActive = Date.now();
  if (details.wordCount) {
      langProgress.totalWordsTyped += details.wordCount;
  }

  // Level Up Logic (Simple: Level = 1 + XP/500)
  const newLevel = 1 + Math.floor(langProgress.xp / 500);
  if (newLevel > langProgress.level) {
      langProgress.level = newLevel;
  }

  // Check for Stage Unlock (Typing Mode)
  if (type === 'typing' && details.passed && details.stageId !== undefined) {
      if (details.stageId === langProgress.maxUnlockedStage) {
          langProgress.maxUnlockedStage += 1;
      }
  }

  updatedUser.progress[language] = langProgress;

  // Global Streak Logic
  if (isNewDay) {
      // Check if consecutive day
      const last = new Date(user.lastActiveDate);
      const curr = new Date(today);
      const diffTime = Math.abs(curr.getTime() - last.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 

      if (diffDays === 1) {
          updatedUser.currentStreak += 1;
          if (updatedUser.currentStreak > updatedUser.maxStreak) {
              updatedUser.maxStreak = updatedUser.currentStreak;
          }
      } else if (diffDays > 1) {
          updatedUser.currentStreak = 1;
      }
      updatedUser.lastActiveDate = today;
  }

  saveUser(updatedUser);

  // 2. Add Log
  const newLog: ActivityLog = {
    id: crypto.randomUUID(),
    timestamp: Date.now(),
    date: today,
    type,
    language,
    summary,
    details,
    xpEarned: xp
  };

  const logs = getLogs();
  const updatedLogs = [newLog, ...logs].slice(0, 100); // Keep last 100
  localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(updatedLogs));

  return { user: updatedUser, log: newLog };
};

// --- Library (Memory Bank) ---

export const getLibrary = (): UserContent[] => {
    const data = localStorage.getItem(STORAGE_KEY_LIBRARY);
    return data ? JSON.parse(data) : [];
};

export const saveLibraryItem = (item: UserContent) => {
    const items = getLibrary();
    const existingIdx = items.findIndex(i => i.id === item.id);
    let updatedItems;
    if (existingIdx >= 0) {
        updatedItems = [...items];
        updatedItems[existingIdx] = item;
    } else {
        updatedItems = [item, ...items];
    }
    localStorage.setItem(STORAGE_KEY_LIBRARY, JSON.stringify(updatedItems));
};

export const deleteLibraryItem = (id: string) => {
    const items = getLibrary().filter(i => i.id !== id);
    localStorage.setItem(STORAGE_KEY_LIBRARY, JSON.stringify(items));
};

// --- Writing Tree ---

export const getWritingTree = (): WritingNode[] => {
    const data = localStorage.getItem(STORAGE_KEY_TREE);
    return data ? JSON.parse(data) : [];
};

export const saveWritingTree = (nodes: WritingNode[]) => {
    localStorage.setItem(STORAGE_KEY_TREE, JSON.stringify(nodes));
};

// --- Vocabulary ---

export const getVocabulary = (): VocabularyItem[] => {
    const data = localStorage.getItem(STORAGE_KEY_VOCAB);
    return data ? JSON.parse(data) : [];
};

export const saveVocabularyItem = (item: VocabularyItem) => {
    const items = getVocabulary();
    // Prevent duplicates by word
    if (items.some(i => i.word.toLowerCase() === item.word.toLowerCase() && i.language === item.language)) {
        return; 
    }
    const updated = [item, ...items];
    localStorage.setItem(STORAGE_KEY_VOCAB, JSON.stringify(updated));
};

export const deleteVocabularyItem = (id: string) => {
    const items = getVocabulary().filter(i => i.id !== id);
    localStorage.setItem(STORAGE_KEY_VOCAB, JSON.stringify(items));
};

import React, { useMemo, useState } from 'react';
import { UserProfile, ActivityLog, Language, LanguageProgress, CEFRLevel } from '../types';
import { getLogs, ensureLanguageProgress } from '../services/storageService';
import { Trophy, Flame, Calendar, Clock, PenTool, Type, Zap, TrendingUp, TrendingDown, Activity, Check, Globe, Settings, GraduationCap, ChevronDown, User, LogOut } from 'lucide-react';
import { SUPPORTED_LANGUAGES } from '../constants';
import AssessmentView from './AssessmentView';

interface ProfileViewProps {
  user: UserProfile;
  onUpdateUser: (user: UserProfile) => void;
  onLogout: () => void;
}

const ProfileView: React.FC<ProfileViewProps> = ({ user, onUpdateUser, onLogout }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'settings'>('overview');
  const [showAssessment, setShowAssessment] = useState(false);

  const logs = getLogs();
  const currentProgress = user.progress[user.learningLanguage];

  // --- Analytics & Calculations ---
  const analytics = useMemo(() => {
    const now = new Date();
    const oneDay = 24 * 60 * 60 * 1000;

    // Helper: Get logs for specific language
    const langLogs = logs.filter(l => l.language === user.learningLanguage);

    // 1. Calendar Data (Current Month)
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth();
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const firstDayOfMonth = new Date(currentYear, currentMonth, 1).getDay(); // 0 = Sun

    const calendarDays = [];
    // Padding for empty start days
    for (let i = 0; i < firstDayOfMonth; i++) {
        calendarDays.push({ date: '', active: false, future: false });
    }
    // Days
    for (let d = 1; d <= daysInMonth; d++) {
        const dateObj = new Date(currentYear, currentMonth, d);
        const dateStr = dateObj.toISOString().split('T')[0];
        const isActive = logs.some(l => l.date === dateStr);
        const isFuture = dateObj > now;
        calendarDays.push({ date: dateStr, dayNum: d, active: isActive, future: isFuture });
    }

    // 2. Trends: Avg Words (Last 30 Days)
    const thirtyDaysAgo = new Date(now.getTime() - (30 * oneDay));
    const last30DaysLogs = langLogs.filter(l => new Date(l.timestamp) >= thirtyDaysAgo);
    const totalWords30 = last30DaysLogs.reduce((acc, l) => acc + (l.details.wordCount || 0), 0);
    const avgWordsDaily = last30DaysLogs.length > 0 ? Math.round(totalWords30 / 30) : 0;

    // 3. Trends: Error Rate Change (Last 7 Days vs Previous 7)
    const sevenDaysAgo = new Date(now.getTime() - (7 * oneDay));
    const fourteenDaysAgo = new Date(now.getTime() - (14 * oneDay));

    const week1Logs = langLogs.filter(l => new Date(l.timestamp) >= sevenDaysAgo);
    const week2Logs = langLogs.filter(l => new Date(l.timestamp) >= fourteenDaysAgo && new Date(l.timestamp) < sevenDaysAgo);

    const getAvgError = (ls: ActivityLog[]) => {
        if (!ls.length) return 0;
        const totalAcc = ls.reduce((acc, l) => acc + (l.details.accuracy || 0), 0);
        const avgAcc = totalAcc / ls.length;
        return 100 - avgAcc;
    };

    const currentErrorRate = getAvgError(week1Logs);
    const prevErrorRate = getAvgError(week2Logs);
    const errorRateDiff = currentErrorRate - prevErrorRate; 

    // 4. Accuracy Trend (Last 7 active sessions)
    const recentSessions = [...langLogs]
        .sort((a, b) => a.timestamp - b.timestamp)
        .slice(-7);

    const accuracyTrend = recentSessions.map(l => ({
        date: l.date.slice(5),
        acc: l.details.accuracy || 0,
        type: l.type
    }));

    const nativeLangCode = SUPPORTED_LANGUAGES.find(l => l.id === user.nativeLanguage)?.code || 'en-US';

    return {
        calendarDays,
        avgWordsDaily,
        currentErrorRate,
        prevErrorRate,
        errorRateDiff,
        accuracyTrend,
        monthName: now.toLocaleString(nativeLangCode, { month: 'long' })
    };
  }, [logs, user.learningLanguage, user.nativeLanguage]);

  // --- Actions ---

  const handleLanguageSwitch = (lang: Language) => {
    let updatedUser = { ...user, learningLanguage: lang };
    updatedUser = ensureLanguageProgress(updatedUser, lang);
    onUpdateUser(updatedUser);
  };

  const handleLevelChange = (level: CEFRLevel) => {
    const updatedUser = { ...user };
    if (!updatedUser.progress[user.learningLanguage]) {
        // Ensure progress exists before setting level
        ensureLanguageProgress(updatedUser, user.learningLanguage);
    }
    updatedUser.progress[user.learningLanguage].cefrLevel = level;
    onUpdateUser(updatedUser);
    setShowAssessment(false); // Close assessment if open
  };

  // --- Render Helpers ---

  const getLanguageFlag = (lang: string) => {
    return SUPPORTED_LANGUAGES.find(l => l.id === lang)?.flag || '🌐';
  };

  const getLanguageLabel = (lang: string) => {
    return SUPPORTED_LANGUAGES.find(l => l.id === lang)?.label || lang;
  };

  const activeLanguages = (Object.entries(user.progress) as [string, LanguageProgress][])
    .sort(([, a], [, b]) => b.xp - a.xp);

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">

      {/* Header Profile Card */}
      <div className="bg-gradient-to-r from-gray-800 to-gray-900 border border-gray-700 p-6 md:p-8 rounded-3xl relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 right-0 p-8 opacity-10">
            <Trophy size={200} />
        </div>

        {/* Log Out Button */}
        <div className="absolute top-4 right-4 z-20">
            <button 
                onClick={onLogout}
                className="flex items-center gap-2 px-3 py-1.5 bg-red-500/10 hover:bg-red-500/20 text-red-400 border border-red-500/30 rounded-lg text-xs font-bold transition-colors"
            >
                <LogOut size={14} /> Log Out
            </button>
        </div>

        <div className="flex flex-col md:flex-row items-center gap-8 relative z-10">
            <div className="w-24 h-24 md:w-28 md:h-28 bg-gray-700 rounded-full flex items-center justify-center text-4xl md:text-5xl border-4 border-secondary shadow-lg">
                {getLanguageFlag(user.learningLanguage)}
            </div>

            <div className="text-center md:text-left flex-1">
                <h2 className="text-3xl font-bold text-white mb-2">{user.username}</h2>
                <div className="flex flex-wrap items-center justify-center md:justify-start gap-4 text-gray-300">
                    <span className="flex items-center gap-1 bg-gray-700/50 px-3 py-1 rounded-full text-sm">
                        <Calendar size={14} /> Joined {new Date(user.joinedDate).toLocaleDateString()}
                    </span>
                    <span className="flex items-center gap-1 bg-gray-700/50 px-3 py-1 rounded-full text-sm border border-secondary/30">
                        {user.learningLanguage} • {currentProgress.cefrLevel}
                    </span>
                </div>

                {/* Level / XP Bar for CURRENT language */}
                <div className="mt-6 max-w-md w-full">
                    <div className="flex justify-between text-sm mb-1 font-semibold">
                        <span className="text-secondary">Level {currentProgress.level}</span>
                        <span className="text-gray-400">{currentProgress.xp} XP</span>
                    </div>
                    <div className="h-3 bg-gray-700 rounded-full overflow-hidden w-full">
                        <div 
                            className="h-full bg-gradient-to-r from-primary to-secondary" 
                            style={{ width: `${Math.min(100, (currentProgress.xp % 100))}%` }} 
                        />
                    </div>
                </div>
            </div>

            {/* Main Streak Counter */}
            <div className="flex flex-col items-center p-5 bg-orange-500/10 border border-orange-500/30 rounded-2xl min-w-[140px]">
                <Flame size={36} className="text-orange-500 mb-2 animate-pulse" />
                <span className="text-4xl font-bold text-white">{user.currentStreak}</span>
                <span className="text-xs text-orange-400 uppercase font-bold tracking-wider">Day Streak</span>
            </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-4 border-b border-gray-700 pb-1">
          <button 
            onClick={() => setActiveTab('overview')}
            className={`px-4 py-2 text-sm font-bold flex items-center gap-2 border-b-2 transition-colors ${activeTab === 'overview' ? 'border-secondary text-white' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
          >
            <Activity size={16} /> Overview
          </button>
          <button 
            onClick={() => setActiveTab('settings')}
            className={`px-4 py-2 text-sm font-bold flex items-center gap-2 border-b-2 transition-colors ${activeTab === 'settings' ? 'border-secondary text-white' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
          >
            <Settings size={16} /> Learning Settings
          </button>
      </div>

      {activeTab === 'overview' ? (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
            {/* Left Col: Calendar & Multi-Language Stats */}
            <div className="space-y-6">

                {/* Multi-Language Stats Card */}
                <div className="bg-card border border-gray-700 rounded-2xl p-6">
                    <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                        <Globe size={20} className="text-blue-400" /> Language Progress
                    </h3>
                    <div className="space-y-3">
                        {activeLanguages.map(([lang, prog]) => (
                            <div key={lang} className={`flex items-center gap-3 p-3 rounded-xl border ${lang === user.learningLanguage ? 'bg-secondary/10 border-secondary/30' : 'bg-dark/50 border-gray-800'}`}>
                                <div className="text-2xl">{getLanguageFlag(lang)}</div>
                                <div className="flex-1">
                                    <div className="flex justify-between items-center mb-1">
                                        <span className={`font-semibold text-sm ${lang === user.learningLanguage ? 'text-white' : 'text-gray-400'}`}>
                                            {getLanguageLabel(lang)}
                                        </span>
                                        <span className="text-xs font-bold text-secondary">Lvl {prog.level}</span>
                                    </div>
                                    <div className="w-full h-1.5 bg-gray-800 rounded-full overflow-hidden">
                                        <div className="h-full bg-secondary" style={{ width: `${Math.min(100, (prog.xp % 100))}%` }}></div>
                                    </div>
                                    <div className="text-[10px] text-gray-500 mt-1 flex justify-between">
                                        <span>{prog.totalWordsTyped} words typed</span>
                                        <span>{prog.xp} XP</span>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Calendar */}
                <div className="bg-card border border-gray-700 rounded-2xl p-6">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            <Calendar size={20} className="text-primary" /> {analytics.monthName}
                        </h3>
                        <div className="text-xs text-gray-500 flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full bg-secondary"></span> Active
                        </div>
                    </div>

                    <div className="grid grid-cols-7 gap-2 text-center text-sm">
                        {['S','M','T','W','T','F','S'].map(d => (
                            <div key={d} className="text-gray-500 font-bold text-xs py-1">{d}</div>
                        ))}
                        {analytics.calendarDays.map((d, i) => (
                            <div 
                                key={i} 
                                className={`
                                    aspect-square rounded-lg flex items-center justify-center text-xs relative
                                    ${!d.dayNum ? 'invisible' : ''}
                                    ${d.active ? 'bg-secondary text-white font-bold shadow-lg shadow-secondary/20' : 'bg-gray-800/50 text-gray-500'}
                                    ${d.future ? 'opacity-30' : ''}
                                `}
                            >
                                {d.dayNum}
                                {d.active && <div className="absolute -bottom-1 w-1 h-1 bg-white rounded-full"></div>}
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Middle & Right Col: Analytics & Trends */}
            <div className="lg:col-span-2 space-y-6">

                {/* Habit Trends Cards */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* 30 Day Avg */}
                    <div className="bg-card border border-gray-700 p-5 rounded-2xl flex flex-col justify-between h-32">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs text-gray-400 uppercase font-bold tracking-wider">30-Day Avg Volume</p>
                                <p className="text-3xl font-bold text-white mt-2">{analytics.avgWordsDaily} <span className="text-base font-normal text-gray-500">words/day</span></p>
                            </div>
                            <div className="p-2 bg-blue-500/10 rounded-lg text-blue-400">
                                <Activity size={24} />
                            </div>
                        </div>
                    </div>

                    {/* Error Rate Trend */}
                    <div className="bg-card border border-gray-700 p-5 rounded-2xl flex flex-col justify-between h-32">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="text-xs text-gray-400 uppercase font-bold tracking-wider">Error Rate (Weekly)</p>
                                <div className="flex items-baseline gap-2 mt-2">
                                    <p className="text-3xl font-bold text-white">{analytics.currentErrorRate.toFixed(1)}%</p>
                                    {analytics.prevErrorRate > 0 && (
                                        <span className={`text-sm font-bold flex items-center ${analytics.errorRateDiff <= 0 ? 'text-green-400' : 'text-red-400'}`}>
                                            {analytics.errorRateDiff <= 0 ? <TrendingDown size={14} /> : <TrendingUp size={14} />}
                                            {Math.abs(analytics.errorRateDiff).toFixed(1)}%
                                        </span>
                                    )}
                                </div>
                            </div>
                            <div className={`p-2 rounded-lg ${analytics.errorRateDiff <= 0 ? 'bg-green-500/10 text-green-400' : 'bg-red-500/10 text-red-400'}`}>
                                {analytics.errorRateDiff <= 0 ? <Check size={24} /> : <Activity size={24} />}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Accuracy Graph (Simple Visual) */}
                <div className="bg-card border border-gray-700 p-6 rounded-2xl">
                    <h3 className="text-lg font-bold text-white mb-6">Recent Accuracy Trend</h3>
                    <div className="h-32 flex items-end justify-between gap-2">
                        {analytics.accuracyTrend.length === 0 ? (
                            <div className="w-full h-full flex items-center justify-center text-gray-600 italic">No recent activity</div>
                        ) : (
                            analytics.accuracyTrend.map((item, i) => (
                                <div key={i} className="flex-1 flex flex-col items-center gap-2 group relative">
                                    <div className="absolute -top-8 bg-gray-800 text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-10">
                                        {item.acc}% • {item.type}
                                    </div>
                                    <div 
                                        className={`w-full max-w-[40px] rounded-t-lg transition-all duration-500 hover:brightness-110 ${item.acc >= 90 ? 'bg-green-500' : item.acc >= 70 ? 'bg-yellow-500' : 'bg-red-500'}`} 
                                        style={{ height: `${item.acc}%` }}
                                    />
                                    <span className="text-xs text-gray-500">{item.date}</span>
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {/* Recent History List */}
                <div className="bg-card border border-gray-700 rounded-2xl overflow-hidden">
                    <div className="p-4 border-b border-gray-700 font-bold text-white flex items-center gap-2">
                        <Clock size={18} className="text-gray-400" /> Recent History
                    </div>
                    <div className="divide-y divide-gray-700 max-h-[400px] overflow-y-auto custom-scrollbar">
                        {logs.length === 0 ? (
                            <div className="p-8 text-center text-gray-500">No activity yet. Start training!</div>
                        ) : (
                            logs.map(log => (
                                <div key={log.id} className="p-4 hover:bg-white/5 transition-colors">
                                    <div className="flex justify-between items-start mb-1">
                                        <div className="flex items-center gap-2">
                                            <div className={`p-1.5 rounded-lg ${log.type === 'writing' ? 'bg-purple-500/20 text-purple-300' : 'bg-blue-500/20 text-blue-300'}`}>
                                                {log.type === 'writing' ? <PenTool size={14} /> : <Type size={14} />}
                                            </div>
                                            <span className="font-semibold text-white">{log.summary}</span>
                                        </div>
                                        <span className="text-xs text-gray-500">{new Date(log.timestamp).toLocaleDateString()}</span>
                                    </div>

                                    <div className="flex items-center gap-4 pl-9 text-xs text-gray-400">
                                        <span className="flex items-center gap-1">
                                            {getLanguageFlag(log.language)} {getLanguageLabel(log.language)}
                                        </span>
                                        {log.details.wpm && <span>Speed: <span className="text-gray-200">{log.details.wpm} WPM</span></span>}
                                        {log.details.accuracy && <span>Acc: <span className="text-gray-200">{log.details.accuracy}%</span></span>}
                                        <span className="text-yellow-500/80">+{log.xpEarned} XP</span>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>
          </div>
      ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in fade-in duration-300">

              {/* Language Settings Card */}
              <div className="bg-card border border-gray-700 rounded-2xl p-6 h-fit">
                  <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                      <User size={20} className="text-secondary" /> Language Configuration
                  </h3>

                  <div className="space-y-6">
                      {/* Language Selector */}
                      <div>
                        <label className="text-sm font-bold text-gray-400 mb-2 block">Target Language</label>
                        <div className="relative">
                            <select 
                                value={user.learningLanguage}
                                onChange={(e) => handleLanguageSwitch(e.target.value as Language)}
                                className="w-full appearance-none bg-dark border border-gray-700 text-white rounded-xl py-3 pl-4 pr-10 focus:ring-2 focus:ring-secondary focus:border-transparent outline-none cursor-pointer text-lg"
                            >
                                {SUPPORTED_LANGUAGES.map(l => {
                                    const hasProgress = user.progress[l.id];
                                    return (
                                        <option key={l.id} value={l.id}>
                                            {l.flag} {l.label} {hasProgress ? `(Lvl ${hasProgress.level})` : ''}
                                        </option>
                                    );
                                })}
                            </select>
                            <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-500 pointer-events-none" size={20} />
                        </div>
                        <p className="text-xs text-gray-500 mt-2">Switching languages will save your progress for the current language.</p>
                      </div>

                      {/* Level Selector */}
                      <div>
                        <label className="text-sm font-bold text-gray-400 mb-2 block">Proficiency Level</label>
                        <div className="relative">
                            <select 
                                value={currentProgress.cefrLevel}
                                onChange={(e) => handleLevelChange(e.target.value as CEFRLevel)}
                                className="w-full appearance-none bg-dark border border-gray-700 text-white rounded-xl py-3 pl-4 pr-10 focus:ring-2 focus:ring-secondary focus:border-transparent outline-none cursor-pointer text-lg"
                            >
                                {Object.values(CEFRLevel).map(l => (
                                    <option key={l} value={l}>{l}</option>
                                ))}
                            </select>
                            <GraduationCap className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-500 pointer-events-none" size={20} />
                        </div>
                        <p className="text-xs text-gray-500 mt-2">Manually adjust if you feel the content is too easy or too hard.</p>
                      </div>

                      {/* AI Assessment Trigger */}
                      <div className="pt-4 border-t border-gray-700">
                          <p className="text-sm text-gray-300 mb-3">Not sure about your level?</p>
                          <button 
                             onClick={() => setShowAssessment(true)}
                             className="w-full py-3 bg-blue-600/20 hover:bg-blue-600/30 text-blue-300 border border-blue-600/50 rounded-xl font-bold transition-all flex items-center justify-center gap-2"
                          >
                              <Zap size={18} /> Take AI Level Check
                          </button>
                      </div>
                  </div>
              </div>

              {/* Assessment Area */}
              {showAssessment ? (
                  <div className="bg-card border border-gray-700 rounded-2xl p-6 animate-in slide-in-from-right duration-500">
                       <div className="flex justify-between items-center mb-4">
                           <h3 className="font-bold text-white">Proficiency Assessment</h3>
                           <button onClick={() => setShowAssessment(false)} className="text-gray-500 hover:text-white text-sm">Cancel</button>
                       </div>
                       <AssessmentView language={user.learningLanguage} onLevelSet={handleLevelChange} />
                  </div>
              ) : (
                  <div className="flex flex-col items-center justify-center text-center p-8 bg-gray-900/30 border border-dashed border-gray-800 rounded-2xl">
                      <Zap size={48} className="text-gray-700 mb-4" />
                      <p className="text-gray-500 max-w-xs">
                          Take a level check to let our AI analyze your writing and automatically set your CEFR level.
                      </p>
                  </div>
              )}
          </div>
      )}
    </div>
  );
};

export default ProfileView;

import React, { useState, useEffect } from 'react';
import { Language, CEFRLevel, AppMode, UserProfile } from './types';
import { SUPPORTED_LANGUAGES, NAV_ITEMS } from './constants';
import { getUser, saveUser, ensureLanguageProgress, logoutUser } from './services/storageService';
import TypingView from './components/TypingView';
import WritingView from './components/WritingView';
import LibraryView from './components/LibraryView';
import ProfileView from './components/ProfileView';
import LoginView from './components/LoginView';
import WritingTreeView from './components/WritingTreeView';
import VocabularyView from './components/VocabularyView';
import { GraduationCap, ChevronDown, Menu, Flame, Star } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [mode, setMode] = useState<AppMode>(AppMode.Typing);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [typingInitialData, setTypingInitialData] = useState<{text: string; title: string; notes?: string} | null>(null);

  // Initial Load
  useEffect(() => {
    const loadedUser = getUser();
    if (loadedUser) {
      setUser(loadedUser);
    }
  }, []);

  // Update user wrapper to force re-render on storage change
  const handleUserUpdate = (updatedUser: UserProfile) => {
    setUser(updatedUser);
    saveUser(updatedUser);
  };

  const handleLogout = () => {
    logoutUser();
    setUser(null);
    setMode(AppMode.Typing);
  };

  const handlePracticeFromLibrary = (content: {text: string; title: string; notes?: string}) => {
    setTypingInitialData(content);
    setMode(AppMode.Typing);
  };

  const handleModeChange = (newMode: AppMode) => {
    if (newMode !== AppMode.Typing) {
        setTypingInitialData(null); // Clear custom data if leaving typing or switching explicitly
    }
    setMode(newMode);
    setIsMenuOpen(false);
  };

  if (!user) {
    return <LoginView onLogin={(u) => setUser(u)} />;
  }

  // Derived state for current language stats
  const currentFlag = SUPPORTED_LANGUAGES.find(l => l.id === user.learningLanguage)?.flag || '🌐';
  const currentProgress = user.progress[user.learningLanguage] || { xp: 0, level: 1, cefrLevel: CEFRLevel.A1 };

  const renderContent = () => {
    switch (mode) {
      case AppMode.Typing:
        return (
            <TypingView 
                user={user}
                onComplete={handleUserUpdate}
                initialData={typingInitialData}
            />
        );
      case AppMode.Writing:
        return (
            <WritingView 
                user={user}
                onComplete={handleUserUpdate}
            />
        );
      case AppMode.WritingTree:
        return (
            <WritingTreeView 
                user={user}
                onUpdateUser={handleUserUpdate}
            />
        );
      case AppMode.Library:
        return (
            <LibraryView 
                user={user}
                onPractice={handlePracticeFromLibrary}
            />
        );
      case AppMode.ReadingLog:
        return (
            <LibraryView 
                user={user}
                onPractice={handlePracticeFromLibrary}
                startWithReflection={true}
            />
        );
      case AppMode.Vocabulary:
        return (
            <VocabularyView 
                user={user}
                onUpdateUser={handleUserUpdate}
            />
        );
      case AppMode.Profile:
        return <ProfileView user={user} onUpdateUser={handleUserUpdate} onLogout={handleLogout} />;
      default:
        return <TypingView user={user} onComplete={handleUserUpdate} />;
    }
  };

  return (
    <div className="min-h-screen bg-dark text-gray-200 flex flex-col md:flex-row font-sans selection:bg-secondary/30 selection:text-white">

      {/* Sidebar / Mobile Menu */}
      <aside className={`fixed md:relative z-50 bg-card border-r border-gray-800 h-full w-64 transform ${isMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 transition-transform duration-300 ease-in-out flex flex-col`}>
        <div className="p-6 border-b border-gray-800 flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-primary to-secondary rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg">
                L
            </div>
            <div>
                <h1 className="font-bold text-white tracking-tight">LinguaFlow</h1>
                <p className="text-xs text-gray-500">Mastery via Output</p>
            </div>
        </div>

        {/* Mini User Profile in Sidebar */}
        <div className="p-4 bg-gray-900/50 border-b border-gray-800">
            <div className="flex items-center gap-3 mb-2">
                <div className="w-8 h-8 rounded-full bg-gray-700 flex items-center justify-center border border-gray-600 shadow-sm">
                    {currentFlag}
                </div>
                <div className="flex-1 min-w-0">
                    <div className="font-bold text-sm truncate text-white">{user.username}</div>
                    <div className="text-xs text-gray-500">Lvl {currentProgress.level} • {currentProgress.cefrLevel}</div>
                </div>
                <div className="flex flex-col items-center">
                    <Flame size={14} className="text-orange-500" />
                    <span className="text-xs font-bold text-orange-500">{user.currentStreak}</span>
                </div>
            </div>
            {/* XP Bar */}
            <div className="w-full h-1.5 bg-gray-700 rounded-full overflow-hidden">
                <div className="h-full bg-secondary" style={{ width: `${currentProgress.xp % 100}%` }}></div>
            </div>
            <div className="flex justify-between text-[10px] text-gray-500 mt-1">
                 <span>{currentProgress.xp} XP</span>
                 <span>Next Lvl</span>
            </div>
        </div>

        <nav className="flex-1 p-4 space-y-2">
            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-4 px-2">Practice Modes</div>
            {NAV_ITEMS.map((item) => (
                <button
                    key={item.id}
                    onClick={() => handleModeChange(item.id as AppMode)}
                    className={`
                        w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold outline-none
                        ${mode === item.id 
                            ? 'bg-primary text-white shadow-lg shadow-primary/25' 
                            : 'text-gray-400 hover:text-white hover:bg-gray-800 transition-colors duration-200'
                        }
                    `}
                >
                    {item.icon}
                    {item.label}
                </button>
            ))}
        </nav>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 border-b border-gray-800 bg-card">
            <div className="flex items-center gap-2">
                 <div className="w-8 h-8 bg-gradient-to-br from-primary to-secondary rounded-lg flex items-center justify-center text-white font-bold text-sm">L</div>
                 <span className="font-bold text-white">LinguaFlow</span>
            </div>
            <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="text-white p-2">
                <Menu size={24} />
            </button>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar relative">

            {/* Context Badge */}
            <div className="absolute top-4 right-4 md:top-8 md:right-8 flex items-center gap-2 opacity-50 pointer-events-none">
                <span className="text-4xl">{currentFlag}</span>
                <span className="text-6xl font-black text-gray-800 select-none uppercase -ml-4 z-[-1] tracking-tighter">{user.learningLanguage}</span>
            </div>

            <div className="max-w-6xl mx-auto h-full flex flex-col">
                <div className="mb-6">
                    <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                        {NAV_ITEMS.find(n => n.id === mode)?.label}
                    </h2>
                    <p className="text-gray-500 text-sm">
                        {currentProgress.cefrLevel} Level • {currentProgress.xp} XP total
                    </p>
                </div>

                <div className="flex-1">
                    {renderContent()}
                </div>
            </div>
        </div>
      </main>

      {/* Overlay for mobile menu */}
      {isMenuOpen && (
        <div 
            className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm"
            onClick={() => setIsMenuOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

export enum Language {
  English = 'English',
  Japanese = 'Japanese',
  Korean = 'Korean',
  Spanish = 'Spanish',
  French = 'French',
  German = 'German',
  Chinese = 'Chinese',
  Italian = 'Italian'
}

export enum CEFRLevel {
  A1 = 'A1',
  A2 = 'A2',
  B1 = 'B1',
  B2 = 'B2',
  C1 = 'C1',
  C2 = 'C2'
}

export enum AppMode {
  Assessment = 'assessment',
  Typing = 'typing',
  Writing = 'writing',
  Library = 'library',
  WritingTree = 'writing_tree',
  Profile = 'profile',
  Vocabulary = 'vocabulary'
}

export interface AssessmentResult {
  level: CEFRLevel;
  reasoning: string;
  vocabularyScore: number; // 0-100
  grammarScore: number; // 0-100
}

export interface TypingContent {
  text: string;
  topic: string;
  phoneticGuide?: string; // For Japanese (Romaji), Chinese (Pinyin), etc.
  translation: string;
  keyVocabulary: Array<{
    word: string;
    meaning: string;
    partOfSpeech: string;
  }>;
}

export interface WritingFeedback {
  correctedText: string;
  suggestions: Array<{
    original: string;
    suggestion: string;
    reason: string;
  }>;
  generalComment: string;
  cefrEstimation: CEFRLevel;
}

export interface ReadingReflection {
  topic: string;           // 这篇文章的主题是什么？
  impressivePoint: string; // 哪个观点最让你印象深刻？
  examples: string;        // 作者给出了哪些例子？
  userOpinion: string;     // 你自己的观点是什么？
  summary: string;         // 你能用一句话总结整篇内容吗？
}

export interface UserContent {
  id: string;
  title: string;
  content: string;
  notes: string;
  language: Language;
  createdAt: number;
  reflection?: ReadingReflection;
}

export interface VocabularyItem {
  id: string;
  word: string;
  definition: string;
  exampleSentence: string;
  partOfSpeech: string;
  language: Language;
  createdAt: number;
}

// --- Writing Tree System Types ---

export type NodeType = 'root' | 'chapter' | 'section' | 'snippet' | 'idea';

export interface WritingNode {
  id: string;
  parentId: string | null; // null if it's a top-level project/book
  type: NodeType;
  title: string;
  content: string;
  summary?: string; // AI generated summary
  progress: number; // 0-100
  wordCount: number;
  tags: string[];
  isExpanded?: boolean; // UI state for tree
  createdAt: number;
  updatedAt: number;
}

// --- Gamification & User Types ---

export interface ActivityLog {
  id: string;
  timestamp: number;
  date: string; // YYYY-MM-DD
  type: 'writing' | 'typing' | 'tree_writing' | 'vocabulary';
  language: Language;
  summary: string;
  details: {
    wpm?: number;
    accuracy?: number;
    wordCount?: number;
    feedback?: string;
    nodeTitle?: string;
    word?: string;
    stageId?: number;
    passed?: boolean;
  };
  xpEarned: number;
}

export interface LanguageProgress {
  xp: number;
  level: number;
  cefrLevel: CEFRLevel; // Per-language CEFR
  totalWordsTyped: number;
  lastActive: number;
  maxUnlockedStage: number; // 0-indexed, for Typing Adventure Mode
}

export interface UserProfile {
  username: string;
  nativeLanguage: Language;
  learningLanguage: Language; // Currently selected active language

  // Multi-language progression
  progress: Record<string, LanguageProgress>; // Keyed by Language enum value

  // Global Gamification
  currentStreak: number;
  maxStreak: number;
  lastActiveDate: string; // YYYY-MM-DD

  // History
  joinedDate: number;
}

export interface DailyQuest {
  id: string;
  label: string;
  target: number;
  current: number;
  completed: boolean;
  rewardXP: number;
}

import React, { useState, useEffect } from 'react';
import { Language, CEFRLevel, AppMode, UserProfile } from './types';
import { SUPPORTED_LANGUAGES, NAV_ITEMS } from './constants';
import { getUser, saveUser, ensureLanguageProgress, logoutUser } from './services/storageService';
import TypingView from './components/TypingView';
import WritingView from './components/WritingView';
import LibraryView from './components/LibraryView';
import ProfileView from './components/ProfileView';
import LoginView from './components/LoginView';
import WritingTreeView from './components/WritingTreeView';
import VocabularyView from './components/VocabularyView';
import { GraduationCap, ChevronDown, Menu, Flame, Star } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [mode, setMode] = useState<AppMode>(AppMode.Typing);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [typingInitialData, setTypingInitialData] = useState<{text: string; title: string; notes?: string} | null>(null);

  // Initial Load
  useEffect(() => {
    const loadedUser = getUser();
    if (loadedUser) {
      setUser(loadedUser);
    }
  }, []);

  // Update user wrapper to force re-render on storage change
  const handleUserUpdate = (updatedUser: UserProfile) => {
    setUser(updatedUser);
    saveUser(updatedUser);
  };

  const handleLogout = () => {
    logoutUser();
    setUser(null);
    setMode(AppMode.Typing);
  };

  const handlePracticeFromLibrary = (content: {text: string; title: string; notes?: string}) => {
    setTypingInitialData(content);
    setMode(AppMode.Typing);
  };

  const handleModeChange = (newMode: AppMode) => {
    if (newMode !== AppMode.Typing) {
        setTypingInitialData(null); // Clear custom data if leaving typing or switching explicitly
    }
    setMode(newMode);
    setIsMenuOpen(false);
  };

  if (!user) {
    return <LoginView onLogin={(u) => setUser(u)} />;
  }

  // Derived state for current language stats
  const currentFlag = SUPPORTED_LANGUAGES.find(l => l.id === user.learningLanguage)?.flag || '🌐';
  const currentProgress = user.progress[user.learningLanguage] || { xp: 0, level: 1, cefrLevel: CEFRLevel.A1 };

  const renderContent = () => {
    switch (mode) {
      case AppMode.Typing:
        return (
            <TypingView 
                user={user}
                onComplete={handleUserUpdate}
                initialData={typingInitialData}
            />
        );
      case AppMode.Writing:
        return (
            <WritingView 
                user={user}
                onComplete={handleUserUpdate}
            />
        );
      case AppMode.WritingTree:
        return (
            <WritingTreeView 
                user={user}
                onUpdateUser={handleUserUpdate}
            />
        );
      case AppMode.Library:
        return (
            <LibraryView 
                user={user}
                onPractice={handlePracticeFromLibrary}
            />
        );
      case AppMode.Vocabulary:
        return (
            <VocabularyView 
                user={user}
                onUpdateUser={handleUserUpdate}
            />
        );
      case AppMode.Profile:
        return <ProfileView user={user} onUpdateUser={handleUserUpdate} onLogout={handleLogout} />;
      default:
        return <TypingView user={user} onComplete={handleUserUpdate} />;
    }
  };

  return (
    <div className="min-h-screen bg-dark text-gray-200 flex flex-col md:flex-row font-sans selection:bg-secondary/30 selection:text-white">

      {/* Sidebar / Mobile Menu */}
      <aside className={`fixed md:relative z-50 bg-card border-r border-gray-800 h-full w-64 transform ${isMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 transition-transform duration-300 ease-in-out flex flex-col`}>
        <div className="p-6 border-b border-gray-800 flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-primary to-secondary rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg">
                L
            </div>
            <div>
                <h1 className="font-bold text-white tracking-tight">LinguaFlow</h1>
                <p className="text-xs text-gray-500">Mastery via Output</p>
            </div>
        </div>

        {/* Mini User Profile in Sidebar */}
        <div className="p-4 bg-gray-900/50 border-b border-gray-800">
            <div className="flex items-center gap-3 mb-2">
                <div className="w-8 h-8 rounded-full bg-gray-700 flex items-center justify-center border border-gray-600 shadow-sm">
                    {currentFlag}
                </div>
                <div className="flex-1 min-w-0">
                    <div className="font-bold text-sm truncate text-white">{user.username}</div>
                    <div className="text-xs text-gray-500">Lvl {currentProgress.level} • {currentProgress.cefrLevel}</div>
                </div>
                <div className="flex flex-col items-center">
                    <Flame size={14} className="text-orange-500" />
                    <span className="text-xs font-bold text-orange-500">{user.currentStreak}</span>
                </div>
            </div>
            {/* XP Bar */}
            <div className="w-full h-1.5 bg-gray-700 rounded-full overflow-hidden">
                <div className="h-full bg-secondary" style={{ width: `${currentProgress.xp % 100}%` }}></div>
            </div>
            <div className="flex justify-between text-[10px] text-gray-500 mt-1">
                 <span>{currentProgress.xp} XP</span>
                 <span>Next Lvl</span>
            </div>
        </div>

        <nav className="flex-1 p-4 space-y-2">
            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-4 px-2">Practice Modes</div>
            {NAV_ITEMS.map((item) => (
                <button
                    key={item.id}
                    onClick={() => handleModeChange(item.id as AppMode)}
                    className={`
                        w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold outline-none
                        ${mode === item.id 
                            ? 'bg-primary text-white shadow-lg shadow-primary/25' 
                            : 'text-gray-400 hover:text-white hover:bg-gray-800 transition-colors duration-200'
                        }
                    `}
                >
                    {item.icon}
                    {item.label}
                </button>
            ))}
        </nav>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 border-b border-gray-800 bg-card">
            <div className="flex items-center gap-2">
                 <div className="w-8 h-8 bg-gradient-to-br from-primary to-secondary rounded-lg flex items-center justify-center text-white font-bold text-sm">L</div>
                 <span className="font-bold text-white">LinguaFlow</span>
            </div>
            <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="text-white p-2">
                <Menu size={24} />
            </button>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar relative">

            {/* Context Badge */}
            <div className="absolute top-4 right-4 md:top-8 md:right-8 flex items-center gap-2 opacity-50 pointer-events-none">
                <span className="text-4xl">{currentFlag}</span>
                <span className="text-6xl font-black text-gray-800 select-none uppercase -ml-4 z-[-1] tracking-tighter">{user.learningLanguage}</span>
            </div>

            <div className="max-w-6xl mx-auto h-full flex flex-col">
                <div className="mb-6">
                    <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                        {NAV_ITEMS.find(n => n.id === mode)?.label}
                    </h2>
                    <p className="text-gray-500 text-sm">
                        {currentProgress.cefrLevel} Level • {currentProgress.xp} XP total
                    </p>
                </div>

                <div className="flex-1">
                    {renderContent()}
                </div>
            </div>
        </div>
      </main>

      {/* Overlay for mobile menu */}
      {isMenuOpen && (
        <div 
            className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm"
            onClick={() => setIsMenuOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserProfile, UserContent, ReadingReflection } from '../types';
import { getLibrary, saveLibraryItem, deleteLibraryItem } from '../services/storageService';
import { analyzeReadingContent } from '../services/geminiService';
import { Plus, Trash2, Save, BookOpen, PenLine, Type, ArrowLeft, Sparkles, BrainCircuit, ChevronDown, ChevronUp, FileText } from 'lucide-react';

interface LibraryViewProps {
  user: UserProfile;
  onPractice: (content: { text: string; title: string; notes?: string }) => void;
}

const LibraryView: React.FC<LibraryViewProps> = ({ user, onPractice }) => {
  const [items, setItems] = useState<UserContent[]>([]);
  const [selectedItem, setSelectedItem] = useState<UserContent | null>(null);
  const [isCreating, setIsCreating] = useState(false);

  // Form State
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [notes, setNotes] = useState('');

  // Reflection State
  const [showReflection, setShowReflection] = useState(false);
  const [reflectionTopic, setReflectionTopic] = useState('');
  const [reflectionPoint, setReflectionPoint] = useState('');
  const [reflectionExamples, setReflectionExamples] = useState('');
  const [reflectionOpinion, setReflectionOpinion] = useState('');
  const [reflectionSummary, setReflectionSummary] = useState('');
  const [isAnalyzingReflection, setIsAnalyzingReflection] = useState(false);

  useEffect(() => {
    setItems(getLibrary().filter(i => i.language === user.learningLanguage));
  }, [user.learningLanguage]);

  useEffect(() => {
    if (selectedItem) {
      setTitle(selectedItem.title);
      setContent(selectedItem.content);
      setNotes(selectedItem.notes);

      // Load reflection data if exists
      if (selectedItem.reflection) {
          setShowReflection(true);
          setReflectionTopic(selectedItem.reflection.topic || '');
          setReflectionPoint(selectedItem.reflection.impressivePoint || '');
          setReflectionExamples(selectedItem.reflection.examples || '');
          setReflectionOpinion(selectedItem.reflection.userOpinion || '');
          setReflectionSummary(selectedItem.reflection.summary || '');
      } else {
          setShowReflection(false);
          resetReflectionFields();
      }

      setIsCreating(false);
    }
  }, [selectedItem]);

  const resetReflectionFields = () => {
      setReflectionTopic('');
      setReflectionPoint('');
      setReflectionExamples('');
      setReflectionOpinion('');
      setReflectionSummary('');
  };

  const handleCreateNew = () => {
    setSelectedItem(null);
    setIsCreating(true);
    setTitle('');
    setContent('');
    setNotes('');
    setShowReflection(false); // Default to standard notes
    resetReflectionFields();
  };

  const handleCreateReadingLog = () => {
    handleCreateNew();
    setShowReflection(true); // Force open the Reflection tab
  };

  const handleSave = () => {
    if (!title.trim() || !content.trim()) return;

    // Construct reflection object if enabled or populated
    let reflection: ReadingReflection | undefined = undefined;
    if (showReflection) {
        reflection = {
            topic: reflectionTopic,
            impressivePoint: reflectionPoint,
            examples: reflectionExamples,
            userOpinion: reflectionOpinion,
            summary: reflectionSummary
        };
    }

    const newItem: UserContent = {
      id: selectedItem?.id || crypto.randomUUID(),
      title,
      content,
      notes,
      language: user.learningLanguage,
      createdAt: selectedItem?.createdAt || Date.now(),
      reflection
    };

    saveLibraryItem(newItem);
    setItems(getLibrary().filter(i => i.language === user.learningLanguage));
    setSelectedItem(newItem);
    setIsCreating(false);
  };

  const handleDelete = (id: string) => {
    deleteLibraryItem(id);
    setItems(prev => prev.filter(i => i.id !== id));
    if (selectedItem?.id === id) {
      setSelectedItem(null);
      setIsCreating(false);
    }
  };

  const handleAnalyzeReflection = async () => {
      if (!content.trim()) return;
      setIsAnalyzingReflection(true);
      try {
          const result = await analyzeReadingContent(content, user.learningLanguage, user.nativeLanguage);
          if (result.topic) setReflectionTopic(result.topic);
          if (result.impressivePoint) setReflectionPoint(result.impressivePoint);
          if (result.examples) setReflectionExamples(result.examples);
          if (result.summary) setReflectionSummary(result.summary);
      } catch (e) {
          console.error(e);
      } finally {
          setIsAnalyzingReflection(false);
      }
  };

  return (
    <div className="flex flex-col lg:flex-row h-[calc(100vh-140px)] gap-6">
      {/* Sidebar List */}
      <div className={`w-full lg:w-1/3 bg-card border border-gray-700 rounded-xl flex flex-col ${selectedItem || isCreating ? 'hidden lg:flex' : 'flex'}`}>
        <div className="p-4 border-b border-gray-700 flex justify-between items-center bg-gray-900/50">
          <h2 className="font-bold text-white flex items-center gap-2">
            <BookOpen size={20} className="text-secondary" />
            Memory Bank
          </h2>
          <div className="flex gap-2">
              <button 
                onClick={handleCreateReadingLog}
                className="p-2 bg-secondary/20 hover:bg-secondary/30 text-secondary border border-secondary/50 rounded-lg transition-colors"
                title="New Reading Reflection Log"
              >
                <BrainCircuit size={20} />
              </button>
              <button 
                onClick={handleCreateNew}
                className="p-2 bg-primary hover:bg-primary/80 rounded-lg text-white transition-colors shadow-lg shadow-primary/20"
                title="Add new standard memory"
              >
                <Plus size={20} />
              </button>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
          {items.length === 0 ? (
             <div className="flex flex-col items-center justify-center h-64 text-gray-500 text-sm text-center px-4">
                <Sparkles className="mb-4 opacity-30" size={48} />
                <p className="text-lg font-medium text-gray-400 mb-2">Empty Bank</p>
                <p className="mb-6 opacity-70 max-w-[200px]">Save articles, book excerpts, or thoughts here.</p>
                <div className="flex flex-col gap-3 w-full max-w-[200px]">
                    <button 
                        onClick={handleCreateNew}
                        className="flex items-center justify-center gap-2 py-2 px-4 bg-gray-800 hover:bg-gray-700 border border-gray-700 rounded-lg transition-colors font-medium text-white"
                    >
                        <FileText size={16} /> Add Text
                    </button>
                    <button 
                        onClick={handleCreateReadingLog}
                        className="flex items-center justify-center gap-2 py-2 px-4 bg-secondary/10 hover:bg-secondary/20 border border-secondary/30 text-secondary rounded-lg transition-colors font-medium"
                    >
                        <BrainCircuit size={16} /> Log Reading
                    </button>
                </div>
             </div>
          ) : (
            items.map(item => (
              <button
                key={item.id}
                onClick={() => setSelectedItem(item)}
                className={`w-full text-left p-3 rounded-lg transition-colors border ${selectedItem?.id === item.id ? 'bg-secondary/20 border-secondary text-white' : 'border-transparent text-gray-300 hover:bg-gray-800'}`}
              >
                <div className="font-semibold truncate flex items-center gap-2">
                    {item.reflection ? <BrainCircuit size={14} className="text-secondary shrink-0" /> : <FileText size={14} className="text-gray-500 shrink-0" />}
                    <span className="truncate">{item.title}</span>
                </div>
                <div className="text-xs text-gray-500 mt-1 truncate pl-6">{item.content.substring(0, 40)}...</div>
              </button>
            ))
          )}
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`w-full flex-1 bg-card border border-gray-700 rounded-xl flex flex-col ${!selectedItem && !isCreating ? 'hidden lg:flex justify-center items-center text-gray-500' : 'flex'}`}>

        {/* Placeholder if nothing selected */}
        {!selectedItem && !isCreating && (
          <div className="flex flex-col items-center opacity-50">
            <BookOpen size={48} className="mb-4" />
            <p>Select a memory to review or add a new one.</p>
          </div>
        )}

        {/* Editor / Reader View */}
        {(selectedItem || isCreating) && (
          <div className="flex flex-col h-full">
            {/* Toolbar */}
            <div className="p-4 border-b border-gray-700 flex justify-between items-center gap-4 bg-gray-900/20">
              <div className="flex items-center gap-2 flex-1">
                 <button className="lg:hidden p-2 text-gray-400" onClick={() => {setSelectedItem(null); setIsCreating(false)}}>
                    <ArrowLeft size={20} />
                 </button>
                 <input 
                    type="text" 
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    placeholder="Title (e.g., Favorite Poem, Daily Mantra)"
                    className="bg-transparent text-lg font-bold text-white outline-none w-full placeholder-gray-600"
                 />
              </div>
              <div className="flex items-center gap-2">
                 {!isCreating && (
                    <button 
                        onClick={() => handleDelete(selectedItem!.id)}
                        className="p-2 text-gray-500 hover:text-red-400 hover:bg-red-900/10 rounded-lg transition-colors"
                        title="Delete"
                    >
                        <Trash2 size={20} />
                    </button>
                 )}
                 <button 
                    onClick={handleSave}
                    className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-500 text-white rounded-lg font-medium transition-colors shadow-lg shadow-green-900/20"
                 >
                    <Save size={18} /> Save
                 </button>
              </div>
            </div>

            {/* Split View: Content & Notes/Reflection */}
            <div className="flex-1 flex flex-col md:flex-row overflow-hidden divide-y md:divide-y-0 md:divide-x divide-gray-700">
                {/* Source Content */}
                <div className="flex-1 flex flex-col p-4 overflow-y-auto custom-scrollbar relative group bg-gradient-to-b from-gray-900/0 to-gray-900/10">
                    <div className="flex justify-between items-center mb-2">
                         <span className="text-xs font-bold text-gray-500 uppercase tracking-wider">Passage Content</span>
                         {!isCreating && (
                             <button 
                                onClick={() => onPractice({ text: content, title, notes })}
                                className="text-xs flex items-center gap-1 bg-blue-600/20 text-blue-400 px-3 py-1.5 rounded-full hover:bg-blue-600/40 transition-colors font-medium border border-blue-500/30"
                             >
                                <Type size={12} /> Practice in Drill
                             </button>
                         )}
                    </div>
                    <textarea 
                        value={content}
                        onChange={(e) => setContent(e.target.value)}
                        placeholder="Paste a beautiful paragraph, a quote, or an article snippet here..."
                        className="flex-1 bg-transparent resize-none outline-none text-gray-200 leading-relaxed custom-scrollbar placeholder-gray-700 text-lg font-serif"
                    />
                </div>

                {/* Right Panel: Notes & Deep Reading Log */}
                <div className="flex-1 flex flex-col bg-dark/20 overflow-hidden">
                    {/* Toggle */}
                    <div className="flex border-b border-gray-700">
                        <button 
                            onClick={() => setShowReflection(false)}
                            className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-colors ${!showReflection ? 'text-white bg-transparent border-b-2 border-primary' : 'text-gray-500 hover:text-gray-300 border-b-2 border-transparent bg-black/20'}`}
                        >
                            <PenLine size={14} className="inline mr-1 -mt-0.5" /> Quick Notes
                        </button>
                        <button 
                             onClick={() => setShowReflection(true)}
                             className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-colors ${showReflection ? 'text-secondary bg-secondary/5 border-b-2 border-secondary' : 'text-gray-500 hover:text-gray-300 border-b-2 border-transparent bg-black/20'}`}
                        >
                            <BrainCircuit size={14} className="inline mr-1 -mt-0.5" /> Deep Reading Log
                        </button>
                    </div>

                    {showReflection ? (
                        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-4 bg-secondary/5">
                            <div className="flex justify-between items-center">
                                <h4 className="text-sm font-bold text-secondary flex items-center gap-2">
                                    <Sparkles size={14} /> Guided Reflection
                                </h4>
                                <button 
                                    onClick={handleAnalyzeReflection}
                                    disabled={!content.trim() || isAnalyzingReflection}
                                    className="text-xs flex items-center gap-1 bg-secondary text-white px-3 py-1.5 rounded-lg hover:bg-secondary/90 transition-colors disabled:opacity-50 shadow-lg shadow-secondary/20"
                                >
                                    {isAnalyzingReflection ? <Sparkles size={12} className="animate-spin" /> : <BrainCircuit size={12} />} 
                                    {isAnalyzingReflection ? 'Analyzing...' : 'AI Analyze Text'}
                                </button>
                            </div>

                            {!content.trim() && (
                                <div className="p-3 bg-yellow-900/20 border border-yellow-800/30 text-yellow-500 text-xs rounded-lg">
                                    Paste your text on the left to use AI analysis.
                                </div>
                            )}

                            <div className="space-y-4">
                                <div>
                                    <label className="block text-xs font-bold text-gray-400 mb-1.5">What is the main topic?</label>
                                    <input 
                                        type="text" 
                                        value={reflectionTopic}
                                        onChange={e => setReflectionTopic(e.target.value)}
                                        className="w-full bg-dark border border-gray-700 rounded-lg p-2.5 text-sm text-white focus:border-secondary outline-none transition-colors"
                                        placeholder="e.g. The benefits of daily writing..."
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-400 mb-1.5">Most impressive/key point?</label>
                                    <textarea 
                                        value={reflectionPoint}
                                        onChange={e => setReflectionPoint(e.target.value)}
                                        className="w-full bg-dark border border-gray-700 rounded-lg p-2.5 text-sm text-white focus:border-secondary outline-none resize-none h-20 transition-colors"
                                        placeholder="What stood out to you?"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-400 mb-1.5">Examples given by author?</label>
                                    <textarea 
                                        value={reflectionExamples}
                                        onChange={e => setReflectionExamples(e.target.value)}
                                        className="w-full bg-dark border border-gray-700 rounded-lg p-2.5 text-sm text-white focus:border-secondary outline-none resize-none h-20 transition-colors"
                                        placeholder="List examples mentioned..."
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-400 mb-1.5">Your own opinion?</label>
                                    <textarea 
                                        value={reflectionOpinion}
                                        onChange={e => setReflectionOpinion(e.target.value)}
                                        className="w-full bg-dark border border-gray-700 rounded-lg p-2.5 text-sm text-white focus:border-secondary outline-none resize-none h-20 transition-colors"
                                        placeholder="Do you agree? Why or why not?"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-400 mb-1.5">One sentence summary</label>
                                    <textarea 
                                        value={reflectionSummary}
                                        onChange={e => setReflectionSummary(e.target.value)}
                                        className="w-full bg-dark border border-gray-700 rounded-lg p-2.5 text-sm text-white focus:border-secondary outline-none resize-none h-16 transition-colors"
                                        placeholder="Summarize the core message..."
                                    />
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col p-4 overflow-y-auto custom-scrollbar">
                            <textarea 
                                value={notes}
                                onChange={(e) => setNotes(e.target.value)}
                                placeholder="Write vocabulary notes, grammar breakdowns, or your thoughts here..."
                                className="flex-1 bg-transparent resize-none outline-none text-yellow-100/80 font-mono text-sm leading-relaxed custom-scrollbar placeholder-gray-700/50"
                            />
                        </div>
                    )}
                </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default LibraryView;

